#include <WiFi.h>

void setup() {
  Serial.begin(115200);

  // Set WiFi to station mode and disconnect from any network
  WiFi.mode(WIFI_STA);
  WiFi.disconnect();
  delay(100);

  Serial.println("Setup completed.");
}

void loop() {
  Serial.println("Starting Wi-Fi scan...");

  // WiFi.scanNetworks returns the number of networks found
  int n = WiFi.scanNetworks();
  Serial.println("Scan complete.");

  if (n == 0) {
    Serial.println("No networks found.");
  } else {
    Serial.print(n);
    Serial.println(" networks found:");
    Serial.println("-----------------------------------------------------------------------");
    Serial.printf("%-30s | %-17s | %-4s | %-4s\n", "SSID", "BSSID", "RSSI", "CH");
    Serial.println("-----------------------------------------------------------------------");

    for (int i = 0; i < n; ++i) {
      // Print SSID, BSSID, RSSI, and Channel number
      Serial.printf("%-30s | %-17s | %-4d | %-4d\n", 
                    WiFi.SSID(i).c_str(), 
                    WiFi.BSSIDstr(i).c_str(), 
                    WiFi.RSSI(i), 
                    WiFi.channel(i));
      delay(10);
    }
  }
  Serial.println("-----------------------------------------------------------------------\n");

  // Wait 10 seconds before scanning again
  delay(10000);
}
